package net.officefloor.hq.app.person;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateImport {
    // Every line is checked before any is stored, by the person form's rules: name,grade,terms,contact (the last two may be
    // absent or blank). A line whose name matches a person on the sheet (by name or alias, as names are compared) updates
    // them, checked as their edit form would be; any other line adds, and is refused when its name is used on the sheet's
    // tree as a name or alias. A contact already used by someone else on the sheet is refused, as is a name, contact or
    // matched person repeated in the import (ignoring case). Blank lines are skipped; an import with no line is refused.
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody ImportRequest body, People people,
            Out<ImportedPeople> out) throws InvalidPersonException {
        String sheet = sheetId.trim();
        String text = body == null || body.text() == null ? "" : body.text();
        List<ImportedPeople.Line> lines = new ArrayList<>();
        Set<String> names = new HashSet<>();
        Set<String> contacts = new HashSet<>();
        Set<Long> matched = new HashSet<>();
        int n = 0;
        for (String line : text.split("\\r?\\n")) {
            n++;
            if (line.isBlank()) {
                continue;
            }
            String[] fields = line.split(",", -1);
            if (fields.length < 2 || fields.length > 4) {
                throw new InvalidPersonException("Line " + n + ": type name,grade,terms,contact.");
            }
            try {
                PersonRequest request = PersonRules.parse(new PersonRequest(fields[0], fields[1], null, null,
                        fields.length > 2 ? fields[2] : "", fields.length > 3 ? fields[3] : ""));
                if (!names.add(request.name().toLowerCase(Locale.ROOT))) {
                    throw new InvalidPersonException("The name " + request.name() + " is given twice in the import.");
                }
                if (request.contact() != null && !contacts.add(request.contact())) {
                    throw new InvalidPersonException("The contact " + request.contact() + " is given twice in the import.");
                }
                Person existing = people.findByName(sheet, request.name());
                if (existing != null) {
                    if (!matched.add(existing.id())) {
                        throw new InvalidPersonException(existing.name() + " is given twice in the import.");
                    }
                    if (people.aliasClashes(existing)) {
                        throw new InvalidPersonException("An alias of theirs is already in use on the sheet's tree.");
                    }
                } else if (people.nameTaken(sheet, request.name(), -1)) {
                    throw new InvalidPersonException("The name is already in use.");
                }
                if (request.contact() != null
                        && people.contactTaken(sheet, request.contact(), existing == null ? -1 : existing.id())) {
                    throw new InvalidPersonException("The contact is already in use.");
                }
                lines.add(new ImportedPeople.Line(request, existing));
            } catch (InvalidPersonException e) {
                throw new InvalidPersonException("Line " + n + ": " + e.getMessage());
            }
        }
        if (lines.isEmpty()) {
            throw new InvalidPersonException("Paste at least one line of name,grade,terms,contact.");
        }
        out.set(new ImportedPeople(lines));
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Figures;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupLines;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

public class AddImportedPeople {
    // Each checked line is stored in order. A new person is added as the person form adds one: PERSON_ADDED, then its
    // ROLLUP lines. A matched person is updated as their edit form saves them: they keep their name, their grade is
    // given from the sheet's today unless it is already the one in force then, and their terms and contact are set when
    // the line gives them; PERSON_EDITED, then the ROLLUP lines.
    public void add(@PathVariable("sheetId") String sheetId, @Val ImportedPeople imported, @Val Figures before,
            People people, Sheets sheets, Rollup rollup, ServerHttpConnection connection, Audit audit,
            Out<ImportResponse> result) {
        String sheet = sheetId.trim();
        String user = Audit.user(connection);
        LocalDate today = sheets.today(sheet);
        Figures figures = before;
        int added = 0;
        int updated = 0;
        for (ImportedPeople.Line line : imported.people()) {
            PersonRequest request = line.request();
            Person person = line.existing();
            if (person == null) {
                new AuditPersonAdded().audit(people.add(sheet, request), connection, audit);
                added++;
            } else {
                Person edited = person.with(new PersonRequest(person.name(), request.grade(), null, null,
                        request.terms() != null ? request.terms() : person.terms() == null ? null : person.terms().toString(),
                        request.contact() != null ? request.contact() : person.contact()));
                people.save(edited);
                if (!request.grade().equals(person.gradeOn(today))) {
                    people.gradeFrom(person.id(), today, request.grade());
                }
                Person stored = people.find(sheet, person.id());
                new AuditPersonEdited().audit(person, PersonResponse.from(stored, today), connection, audit);
                updated++;
            }
            figures = RollupLines.record(sheet, user, figures, rollup, audit);
        }
        result.set(new ImportResponse(added, updated));
    }
}
